struct BankAccount {
    private(set) var balance = 100
    mutating func deposit(_ amount: Int) {
        balance += amount
    }
}
var account = BankAccount()
account.deposit(50)
print(account.balance)

fileprivate class SecretManager {
    fileprivate var token = "token123"
}
fileprivate class TokenInspector {
    func printToken() {
        let manager = SecretManager()
        print(manager.token)
    }
}
fileprivate let inspector = TokenInspector()
inspector.printToken()

struct User {
    private var password = "secret"
}
extension User {
    func printPassword() {
        print(password)
    }
}
let user = User()
user.printPassword()

struct StepCounter {
    private(set) var steps = 0
    mutating func addSteps(_ count: Int) {
        steps += count
    }
}
var tracker = StepCounter()
tracker.addSteps(10)
tracker.addSteps(15)
print(tracker.steps)

class Vault {
    private var code = 999
    func reveal() -> Int {
        return code
    }
}
let vault = Vault()
print(vault.reveal())

struct Temperature {
    private var celsius: Double
    init(celsius: Double) {
        self.celsius = celsius
    }
    var fahrenheit: Double {
        return celsius * 1.8 + 32.0
    }
}
let temp = Temperature(celsius: 0.0)
print(Int(temp.fahrenheit))

class ScoreCard {
    fileprivate var score = 10
}
extension ScoreCard {
    func doubleScore() {
        score *= 2
    }
}
let card = ScoreCard()
card.doubleScore()
print(card.score)

struct Wallet {
    private(set) var coins = 50
    mutating func spend(_ amount: Int) {
        if amount <= coins {
            coins -= amount
        }
    }
}
var wallet = Wallet()
wallet.spend(20)
print(wallet.coins)

